from collections import Counter, deque

def transform(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    out=[[bg]*w for _ in range(h)]; seen=set()
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          y,x=q.pop(); comp.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
              seen.add((yy,xx));q.append((yy,xx))
        if len(comp)>=4:
          r0=min(y for y,x in comp);r1=max(y for y,x in comp);c0=min(x for y,x in comp);c1=max(x for y,x in comp)
          for y in range(r0,r1+1):
            for x in range(c0,c1+1):out[y][x]=color
    return out

